def is_prime(n: int) -> bool:
    """判断 97 是不是素数，是就打印 True，不是打印 False。"""
    if n <= 1 or n % 2 == 0:
        return False
    for i in range(3, int(n**0.5)+1, 2):
        if n % i == 0:
            return False
    return True

print(is_prime(97))   # True
```

