def read_file(path):
    """读取文件，抛出异常：找不到或写入失败。"""
    try:
        with open(path, "r", encoding="utf-8") as f:
            return f.read()
    except Exception as e:
        print(f"  {path} 文件读取失败: {e}", file=sys.stderr)
        raise ValueError("无法打开文件")
```

